          presets={colorPresets}
          onChange={(color) => update({ fill: color })}
          ariaLabel={labels.drawColor}
          labels={labels}
        />

        {/* Align toggle */}
        <div className="inline-flex shrink-0 rounded-md bg-media-overlay border border-media-overlay-foreground/15 p-0.5">
          {(["left", "center", "right"] as const).map((align) => (
            <button
              key={align}
              type="button"
              onClick={() => update({ align })}
              aria-label={
                align === "left"
                  ? labels.textAlignLeft
                  : align === "center"
                    ? labels.textAlignCenter
                    : labels.textAlignRight
              }
              aria-pressed={overlay.align === align}
              className={cn(
                "inline-grid min-h-6 min-w-6 place-items-center rounded-sm",
                overlay.align === align
                  ? "bg-media-overlay-foreground text-black"
                  : "text-media-overlay-foreground/80 hover:text-media-overlay-foreground",
              )}
            >
              {align === "left" ? (
                <AlignLeft className="size-3.5" />
              ) : align === "center" ? (
                <AlignCenter className="size-3.5" />
              ) : (
                <AlignRight className="size-3.5" />
              )}
            </button>
          ))}
        </div>

        <Button
          variant="ghost"
          size="icon"
          onClick={onDelete}
          aria-label={labels.textDelete}
          className="size-8 shrink-0 text-[color-mix(in_oklab,var(--destructive)_45%,var(--media-overlay-foreground,currentColor))] hover:bg-destructive/15 hover:text-[color-mix(in_oklab,var(--destructive)_25%,var(--media-overlay-foreground,currentColor))]"
        >
          <Trash2 className="size-4" />
        </Button>
      </div>

      {/* Font size slider */}
      <div className="flex items-center gap-3">
        <span className="text-[10px] uppercase tracking-wider text-media-overlay-foreground/75 w-10">
          {labels.textFontSize}
        </span>
        <Slider
          value={[overlay.fontSize]}
          min={MIN_FONT_SIZE}
          max={MAX_FONT_SIZE}
          step={1}
          // Radix emits number[]; Base UI number | readonly number[] (F-cross-13)
          onValueChange={(v) =>
            update({ fontSize: typeof v === "number" ? v : (v[0] ?? overlay.fontSize) })
          }
          aria-label={labels.textFontSize}
          className="flex-1"
        />
        <span className="text-xs font-mono tabular-nums w-8 text-end">
          {formatNumber(overlay.fontSize, locale)}
        </span>
      </div>
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type PointerEvent,
} from "react";
import { cn } from "@/lib/utils";
import { formatNumber } from "../lib/format-number";
import type { MediaEditorResolvedLabels } from "../types";

export interface VideoTrimBarProps {
  /** Source video URL (object URL from a Blob is fine). */
  videoUrl: string;
  /** Trim range in seconds — controlled. */
  startSec: number;
  endSec: number;
  /** Authoritative duration from the source video. */
  durationSec: number;
  /** Number of preview thumbnails to generate (default 8). */
  thumbnailCount?: number;
  labels: MediaEditorResolvedLabels;
  /** BCP 47 locale for the seconds shown. Default: `"en"`. */
  locale?: string;
  onChange: (next: { startSec: number; endSec: number }) => void;
  className?: string;
}

interface FrameThumb {
  t: number;
  url: string;
}

const MIN_DURATION_SEC = 0.5;

/**
 * Two-handle trim bar with auto-generated frame previews.
 *
 * Thumbnails are produced once on mount by seeking an off-DOM <video>
 * to N evenly-spaced timestamps and snapping each frame to a canvas.
 */
export function VideoTrimBar({
  videoUrl,
  startSec,
  endSec,
  durationSec,
  thumbnailCount = 8,
  labels,
  locale,
  onChange,
  className,
}: VideoTrimBarProps) {
  const formatSeconds = (s: number) => formatNumber(s, locale, { min: 1 });
  const trackRef = useRef<HTMLDivElement | null>(null);
  const [thumbs, setThumbs] = useState<FrameThumb[]>([]);
  const draggingRef = useRef<"start" | "end" | null>(null);

  // ─── Generate frame thumbnails ──────────────────────────────────────
  useEffect(() => {
    let cancelled = false;
    if (!videoUrl || durationSec <= 0) return;

    const video = document.createElement("video");
    video.src = videoUrl;
    video.crossOrigin = "anonymous";
    video.muted = true;
    video.preload = "auto";
    video.playsInline = true;

    const cleanup = () => {
      video.removeAttribute("src");
      video.load();
    };

    const onLoaded = async () => {
      const canvas = document.createElement("canvas");
      const w = 64;
      const h = 96;
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext("2d");
      if (!ctx) {
        cleanup();
        return;
      }
      const out: FrameThumb[] = [];
      for (let i = 0; i < thumbnailCount; i++) {
        const t = (i / (thumbnailCount - 1 || 1)) * durationSec;
        await seekTo(video, t);
        if (cancelled) return;
        ctx.drawImage(video, 0, 0, w, h);
        const url = canvas.toDataURL("image/jpeg", 0.6);
        out.push({ t, url });
      }
      if (!cancelled) setThumbs(out);
      cleanup();
    };

    video.addEventListener("loadedmetadata", onLoaded, { once: true });

    return () => {
      cancelled = true;
      video.removeEventListener("loadedmetadata", onLoaded);
      cleanup();
    };
  }, [videoUrl, durationSec, thumbnailCount]);

  // ─── Drag handlers ──────────────────────────────────────────────────
  const positionForX = useCallback(
    (clientX: number): number => {
      const track = trackRef.current;
      if (!track) return 0;
      const rect = track.getBoundingClientRect();
      const ratio = Math.min(1, Math.max(0, (clientX - rect.left) / rect.width));
      return ratio * durationSec;
    },
    [durationSec],
  );

  const handlePointerDown = useCallback(
    (which: "start" | "end") => (e: PointerEvent<HTMLButtonElement>) => {
      e.currentTarget.setPointerCapture?.(e.pointerId);
      draggingRef.current = which;
    },
    [],
  );

  const handlePointerMove = useCallback(
    (e: PointerEvent<HTMLDivElement>) => {
      if (!draggingRef.current) return;
      const next = positionForX(e.clientX);
      if (draggingRef.current === "start") {
        const clamped = Math.min(next, endSec - MIN_DURATION_SEC);
        onChange({ startSec: Math.max(0, clamped), endSec });
      } else {
        const clamped = Math.max(next, startSec + MIN_DURATION_SEC);
        onChange({ startSec, endSec: Math.min(durationSec, clamped) });
      }
    },
    [endSec, startSec, durationSec, onChange, positionForX],
  );

  const handlePointerUp = useCallback(() => {
    draggingRef.current = null;
  }, []);

  // ─── Render ─────────────────────────────────────────────────────────
  const startPct = durationSec > 0 ? (startSec / durationSec) * 100 : 0;
  const endPct = durationSec > 0 ? (endSec / durationSec) * 100 : 100;

  const placeholders = useMemo(
    () => Array.from({ length: thumbnailCount }, (_, i) => i),
    [thumbnailCount],
  );

  return (
    <div className={cn("flex flex-col gap-2 select-none", className)}>
      <div className="flex items-center justify-between text-[10px] font-mono text-media-overlay-foreground/80">
        <span>
          {labels.trimStart}: {labels.trimSeconds(startSec, formatSeconds(startSec))}
        </span>
        <span>
          {labels.trimEnd}: {labels.trimSeconds(endSec, formatSeconds(endSec))}
        </span>
      </div>
      <div
        ref={trackRef}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        className="relative h-16 rounded-md overflow-hidden bg-media-overlay ring-1 ring-media-overlay-foreground/10"
      >
        {/* Frame strip */}
        <div className="absolute inset-0 flex">
          {(thumbs.length ? thumbs : placeholders).map((entry, i) =>
            typeof entry === "number" ? (
              <div
                key={i}
                className="flex-1 bg-linear-to-b from-media-overlay-foreground/5 to-media-overlay-foreground/10 animate-pulse"
              />
            ) : (
              <div
                key={i}
                className="flex-1 bg-cover bg-center"
                style={{ backgroundImage: `url(${entry.url})` }}
              />
            ),
          )}
        </div>
        {/* Dim out trimmed regions */}
        <div
          // dir-ok: trim overlay sized by startPct/endPct on a left-to-right time axis
          className="absolute inset-y-0 left-0 bg-media-overlay"
          style={{ width: `${startPct}%` }}
          aria-hidden
        />
        <div
          // dir-ok: trim overlay sized by startPct/endPct on a left-to-right time axis
          className="absolute inset-y-0 right-0 bg-media-overlay"
          style={{ width: `${100 - endPct}%` }}
          aria-hidden
        />
        {/* Selection outline */}
        <div
          className="absolute inset-y-0 border-y-2 border-media-overlay-foreground pointer-events-none"
          style={{ left: `${startPct}%`, right: `${100 - endPct}%` }}
          aria-hidden
        />
        {/* Start handle */}
        <button
          type="button"
          aria-label={labels.trimStart}
          onPointerDown={handlePointerDown("start")}
          // dir-ok: handle placed by inline style left percent on a left-to-right time axis; -ml centres it
          className="absolute top-0 bottom-0 w-3 -ml-1.5 grid place-items-center bg-media-overlay-foreground text-black cursor-ew-resize touch-none"
          style={{ left: `${startPct}%` }}
        >
          <span className="block h-6 w-0.5 bg-media-overlay" aria-hidden />
        </button>
        {/* End handle */}
        <button
          type="button"
          aria-label={labels.trimEnd}
          onPointerDown={handlePointerDown("end")}
          // dir-ok: handle placed by inline style left percent on a left-to-right time axis; -ml centres it
          className="absolute top-0 bottom-0 w-3 -ml-1.5 grid place-items-center bg-media-overlay-foreground text-black cursor-ew-resize touch-none"
          style={{ left: `${endPct}%` }}
        >
          <span className="block h-6 w-0.5 bg-media-overlay" aria-hidden />
        </button>
      </div>
    </div>
  );
}

function seekTo(video: HTMLVideoElement, t: number): Promise<void> {
  return new Promise((resolve) => {
    const onSeeked = () => {
      video.removeEventListener("seeked", onSeeked);
      resolve();
    };
    video.addEventListener("seeked", onSeeked, { once: true });
    try {
      video.currentTime = Math.min(t, Math.max(0, video.duration || t));
    } catch {
      video.removeEventListener("seeked", onSeeked);
      resolve();
    }
  });
}

"use client";

import * as React from "react";
import type { ComposerMode, MediaEditorResolvedLabels, ValidationError } from "../types";

/**
 * Capture injection seam (P3 S3 — feature-slicing, strategy b: injection
 * surface, R1 VERDICT). Base never statically imports `features/capture/**`
 * — a consumer wires camera capture in by passing `capture={mediaCapture}`
 * (MediaEditorProps.capture) from `@ilinxa/media-editor-capture`. This file
 * owns the context, the extension TYPE, and the surface-props contract the
 * base orchestrator (media-editor.tsx) mounts against — mirroring the
 * renderer-registry pattern used elsewhere in the library.
 */

// ─── Structural mirrors of the capture feature's capture-result shapes ────
// Duplicated here (NOT imported from features/capture/**) so this base file
// carries zero static dependency on the feature folder — the F-S1 inline-copy
// pattern (see cross-procomp-imports precedent). The feature's own
// `CapturedPhoto` / `CapturedVideo` (features/capture/hooks/use-media-capture.ts)
// are kept structurally identical to these so `EditorCamera` type-checks
// as a `CameraSurface` without any cast.

export interface CapturedPhotoLike {
  blob: Blob;
  width: number;
  height: number;
  mimeType: string;
}

export interface CapturedVideoLike {
  blob: Blob;
  durationMs: number;
  mimeType: string;
}

/**
 * Props the base orchestrator passes to whatever camera surface answers the
 * capture extension. Mirrors `EditorCameraProps` (features/capture/parts/
 * editor-camera.tsx) field-for-field — the base mount site passes exactly
 * this shape regardless of which implementation is wired in.
 */
export interface MediaCaptureSurfaceProps {
  /** Composer is open + we should hold a live camera stream. */
  enabled: boolean;
  /** Drives mirror behavior, default facing, and the shutter aria-label. */
  mode: ComposerMode;
  defaultFacing?: "user" | "environment";
  recordAudio?: boolean;
  maxFileSizeMb?: number;
  maxVideoDurationSec?: number;
  captureAspectRatio?: number | null;
  autoAcquireOverride?: boolean;
  /** The editor's fully resolved labels (consumer labels over the defaults). */
  labels: MediaEditorResolvedLabels;
  /** BCP 47 locale for numbers in validation messages (`MediaEditorProps.locale`). */
  locale?: string;
  /** Accepted MIME types for the gallery picker and its validator (`MediaEditorProps.acceptMediaTypes`). */
  acceptMediaTypes?: string[];
  /** Allowed video recording formats in preference order (`MediaEditorProps.videoOutput.mimeTypes`). */
  videoMimeTypes?: string[];
  onPhoto: (photo: CapturedPhotoLike) => void;
  onVideo: (video: CapturedVideoLike) => void;
  /** Loads an image / video file picked from the gallery into the editor. */
  onGalleryFile: (file: File) => void;
  onValidationError?: (error: ValidationError) => void;
  onPermissionDenied?: () => void;
  renderPermissionDenied?: (ctx: {
    retry: () => void;
    usePicker: () => void;
  }) => React.ReactNode;
}

export interface MediaCaptureExtensionContextValue {
  /**
   * The camera surface component to mount when the editor is in the capture
   * stage with a photo/video mode active. No further capture-state
   * accessors are exposed today — capture's own state (permissions, live
   * stream, recording) lives inside the surface component itself, so there's
   * nothing else for the orchestrator to read.
   */
  CameraSurface: React.ComponentType<MediaCaptureSurfaceProps>;
}

export const MediaCaptureExtensionContext =
  React.createContext<MediaCaptureExtensionContextValue | null>(null);

/** Orchestrator-internal read. Null when no `capture` extension is wired. */
export function useCaptureExtensionOptional(): MediaCaptureExtensionContextValue | null {
  return React.useContext(MediaCaptureExtensionContext);
}

/**
 * Public extension contract a consumer installs to enable camera capture.
 * `@ilinxa/media-editor-capture` ships `mediaCapture: MediaCaptureExtension`
 * — pass it straight through: `<MediaEditor capture={mediaCapture} />`.
 * Custom/alternative capture implementations can supply their own `Provider`
 * as long as it renders `MediaCaptureExtensionContext.Provider` with a
 * `CameraSurface` matching `MediaCaptureSurfaceProps`.
 */
export type MediaCaptureExtension = {
  Provider: React.ComponentType<{ children: React.ReactNode }>;
};

import type { MediaEditorResolvedLabels, ValidationError } from "../types";
import { resolveEditorLabels } from "./normalize-labels";
import { formatNumber } from "./format-number";

export interface ValidateGalleryFileOptions {
  /** Message templates (the intake keys of the resolved labels). Default: the English defaults. */
  labels?: Pick<
    MediaEditorResolvedLabels,
    "fileUnknownType" | "fileUnsupportedType" | "fileTooLarge"
  >;
  /** BCP 47 locale for the sizes in the message. Default: `"en"`. */
  locale?: string;
  /**
   * Accepted MIME types (`MediaEditorProps.acceptMediaTypes`); wildcards such
   * as `"video/*"` are allowed. Default `["image/*", "video/*"]`.
   */
  acceptMediaTypes?: readonly string[];
}

/** Default intake accept list. */
export const DEFAULT_ACCEPT_MEDIA_TYPES: readonly string[] = ["image/*", "video/*"];

/** The value for an `<input type="file" accept>` attribute. */
export function acceptAttribute(accept?: readonly string[]): string {
  return (accept && accept.length > 0 ? accept : DEFAULT_ACCEPT_MEDIA_TYPES).join(",");
}

/**
 * True when `fileType` satisfies one entry of `accept`. Entries are exact MIME
 * types (`"video/mp4"`) or `type/*` wildcards; parameters on the file type
 * (`"video/webm;codecs=vp9"`) are ignored. Matching is case-insensitive.
 */
export function matchesAccept(
  fileType: string,
  accept?: readonly string[],
): boolean {
  const list = accept && accept.length > 0 ? accept : DEFAULT_ACCEPT_MEDIA_TYPES;
  const type = (fileType.split(";")[0] ?? "").trim().toLowerCase();
  if (!type) return false;
  return list.some((entry) => {
    const e = (entry.split(";")[0] ?? "").trim().toLowerCase();
    if (!e) return false;
    if (e === "*/*") return true;
    if (e.endsWith("/*")) return type.startsWith(e.slice(0, -1));
    return type === e;
  });
}

/**
 * Gallery/file-intake validation — type + size check. Generic (not
 * camera-specific): lives in BASE so the file/gallery intake surface works
 * with the capture feature slice absent (P3 S3 — the pure-CAPTURE files
 * moved to `features/capture/`, but picking a file off disk isn't a capture
 * concern). Used by the base file-intake surface (media-editor.tsx) AND by
 * `features/capture/parts/editor-camera.tsx`'s gallery button — the feature
 * imports this DIRECTLY (relative into base), never through the barrel.
 *
 * `ValidationError.message` is built from the `intake` labels, so it is
 * translated like the rest of the editor.
 */
export function validateGalleryFile(
  file: File,
  maxFileSizeMb: number,
  options?: ValidateGalleryFileOptions,
): ValidationError | null {
  const labels = options?.labels ?? resolveEditorLabels(undefined);
  // The editor can only edit images and videos, so a custom accept list that
  // names another family (e.g. "application/pdf") still cannot get past this.
  const editable =
    file.type.startsWith("image/") || file.type.startsWith("video/");
  if (!editable || !matchesAccept(file.type, options?.acceptMediaTypes)) {
    return {
      kind: "unsupported-type",
      message: labels.fileUnsupportedType(file.type || labels.fileUnknownType),
      file,
    };
  }
  const bytes = file.size;
  const maxBytes = maxFileSizeMb * 1024 * 1024;
  if (bytes > maxBytes) {
    const sizeMb = bytes / 1024 / 1024;
    return {
      kind: "file-too-large",
      message: labels.fileTooLarge(
        sizeMb,
        maxFileSizeMb,
        formatNumber(sizeMb, options?.locale, { min: 1, grouping: false }),
        formatNumber(maxFileSizeMb, options?.locale, { max: 3, grouping: false }),
      ),
      file,
    };
  }
  return null;
}

// Local default-export wrapper so `React.lazy(() => import("./lazy-editor-canvas"))`
// has a target — `EditorCanvas` itself is a named export. Same-folder
// (intra-component): this carries none of the cross-procomp rewriter hazards
// the media-library `lazy-code-block.tsx` / `lazy-markdown-editor.tsx`
// wrappers document (no category segment to mangle, no other registry item
// involved) — it exists purely for the `React.lazy(...)` default-export
// contract. Compound-component-structure rule: the konva canvas is the
// heavy dep (konva + react-konva) every consumer pulls in, so it gets the
// mandated lazy boundary even though (unlike media-library's viewers) it
// isn't itself droppable — the win here is deferring the konva chunk off
// the editor's initial paint (capture stage / text-only mode never need it).
export { EditorCanvas as default } from "./editor-canvas";

"use client";

import { useEffect, useRef } from "react";
import { isEditableTarget } from "../lib/is-editable-target";

export interface UseGlobalKeydownOptions {
  /** Attach only while true. Default `true`. */
  enabled?: boolean;
  /** Listen in the capture phase. Default `false`. */
  capture?: boolean;
}

/**
 * The one way a registry component listens for keys on `window` (consumer contract C9 /
 * R8). The handler is skipped for events typed into an editable target (see
 * `isEditableTarget`), events another handler already `preventDefault`-ed, and IME
 * composition (`isComposing`, or the legacy keyCode 229).
 *
 * `validate-contract` fails any other `window` / `document` keydown listener in shipped
 * files unless it carries `// keydown-ok: <reason>`.
 *
 * Local copy of the canonical `_template/_snippets/use-global-keydown.ts`.
 */
export function useGlobalKeydown(
  handler: (event: KeyboardEvent) => void,
  { enabled = true, capture = false }: UseGlobalKeydownOptions = {},
): void {
  const handlerRef = useRef(handler);
  useEffect(() => {
    handlerRef.current = handler;
  });
  useEffect(() => {
    if (!enabled || typeof window === "undefined") return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.defaultPrevented || event.isComposing || event.keyCode === 229) return;
      // The real origin: inside an open shadow root `event.target` is retargeted to the host.
      const origin = (typeof event.composedPath === "function" && event.composedPath()[0]) || event.target;
      if (isEditableTarget(origin)) return;
      handlerRef.current(event);
    };
    window.addEventListener("keydown", onKeyDown, capture);
    return () => window.removeEventListener("keydown", onKeyDown, capture);
  }, [enabled, capture]);
}

/**
 * True when a keyboard event's target is somewhere the user is typing or that owns its
 * keys (consumer contract C9 / R8): a text-entry `<input>`, `<textarea>`, `<select>`,
 * contentEditable, `[role="textbox"]`, a widget that owns the arrow keys (`slider`,
 * `spinbutton`, `combobox`, `listbox`), or anything inside `[data-keyboard-ignore]`.
 * Window-level shortcuts must stand down for these.
 *
 * Copy into a component's `lib/` — registry items stay self-contained. Canonical copy:
 * `src/registry/components/_template/_snippets/` (tests next to it).
 */
const NON_TEXT_INPUTS = new Set(["checkbox", "radio", "button", "submit", "reset", "image", "file", "color"]);

export function isEditableTarget(target: EventTarget | null): boolean {
  if (!target || typeof (target as Element).closest !== "function") return false;
  const el = target as HTMLElement;
  if (el.tagName === "INPUT") return !NON_TEXT_INPUTS.has((el as HTMLInputElement).type);
  if (el.tagName === "TEXTAREA" || el.tagName === "SELECT") return true;
  if (el.isContentEditable) return true;
  return (
    el.closest(
      '[contenteditable=""], [contenteditable="true"], [role="textbox"], [role="slider"], [role="spinbutton"], [role="combobox"], [role="listbox"], [data-keyboard-ignore]',
    ) !== null
  );
}

/**
 * Locale-aware number text for the values the editor shows to users (trim
 * seconds, crop-aspect count, adjust values). `locale` is a BCP 47 tag;
 * default `"en"` (deterministic, so server and client render the same text).
 * `grouping: false` drops thousands separators (e.g. "1000" not "1,000"). An invalid tag falls back to `"en"` instead of throwing.
 */
export function formatNumber(
  value: number,
  locale: string | undefined,
  fractionDigits: { min?: number; max?: number; grouping?: boolean } = {},
): string {
  const options: Intl.NumberFormatOptions = {
    useGrouping: fractionDigits.grouping ?? true,
    minimumFractionDigits: fractionDigits.min ?? 0,
    maximumFractionDigits: fractionDigits.max ?? fractionDigits.min ?? 0,
  };
  try {
    return new Intl.NumberFormat(locale ?? "en", options).format(value);
  } catch {
    return new Intl.NumberFormat("en", options).format(value);
  }
}

import type {
  FilterPreset,
  FontOption,
  GradientPreset,
  MediaEditorPresetNames,
  StickerSet,
} from "../types";

/**
 * Applies `labels.presets` (id -> display name) to preset data. Presets whose
 * id has no entry keep their own label; the input is returned as-is (same
 * identity) when there is nothing to rename.
 */

export function renameBackgrounds(
  items: GradientPreset[],
  names: MediaEditorPresetNames["backgrounds"],
): GradientPreset[] {
  if (!names) return items;
  return items.map((g) => (names[g.id] ? { ...g, label: names[g.id]! } : g));
}

export function renameFonts(
  items: FontOption[],
  names: MediaEditorPresetNames["fonts"],
): FontOption[] {
  if (!names) return items;
  return items.map((f) => (names[f.id] ? { ...f, label: names[f.id]! } : f));
}

export function renameFilters(
  items: FilterPreset[],
  names: MediaEditorPresetNames["filters"],
): FilterPreset[] {
  if (!names) return items;
  return items.map((f) => (names[f.id] ? { ...f, label: names[f.id]! } : f));
}

export function renameStickerSets(
  sets: StickerSet[],
  setNames: MediaEditorPresetNames["stickerSets"],
  stickerNames: MediaEditorPresetNames["stickers"],
): StickerSet[] {
  if (!setNames && !stickerNames) return sets;
  return sets.map((set) => ({
    ...set,
    label: setNames?.[set.id] ?? set.label,
    stickers: stickerNames
      ? set.stickers.map((s) =>
          stickerNames[s.id] ? { ...s, alt: stickerNames[s.id]! } : s,
        )
      : set.stickers,
  }));
}

export interface VideoProbe {
  width: number;
  height: number;
  /** Rounded to whole milliseconds; omitted when the container reports no finite duration. */
  durationMs?: number;
}

/**
 * Reads a video blob's intrinsic size and duration through a detached
 * `<video>` element (`loadedmetadata`). Resolves `null` when the metadata does
 * not arrive within `timeoutMs`, the blob fails to decode, or the platform has
 * no DOM — callers fall back to their own defaults. Never rejects.
 */
export function probeVideo(
  blob: Blob,
  timeoutMs = 1500,
): Promise<VideoProbe | null> {
  if (typeof document === "undefined" || typeof URL === "undefined") {
    return Promise.resolve(null);
  }
  return new Promise((resolve) => {
    let url: string;
    try {
      url = URL.createObjectURL(blob);
    } catch {
      resolve(null);
      return;
    }
    const video = document.createElement("video");
    let settled = false;
    const finish = (result: VideoProbe | null) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      video.removeAttribute("src");
      video.load?.();
      URL.revokeObjectURL(url);
      resolve(result);
    };
    const timer = setTimeout(() => finish(null), timeoutMs);
    video.preload = "metadata";
    video.muted = true;
    video.onloadedmetadata = () => {
      const { videoWidth, videoHeight, duration } = video;
      if (!videoWidth || !videoHeight) {
        finish(null);
        return;
      }
      finish({
        width: videoWidth,
        height: videoHeight,
        durationMs: Number.isFinite(duration)
          ? Math.round(duration * 1000)
          : undefined,
      });
    };
    video.onerror = () => finish(null);
    video.src = url;
  });
}

import type { KeyboardEvent } from "react";

/** Elements a keyboard user can land on inside a consumer overlay. */
export const OVERLAY_FOCUSABLE =
  'button:not([disabled]), [href], input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"]), [contenteditable="true"]';

const isJsdom = () =>
  typeof navigator !== "undefined" && /jsdom/i.test(navigator.userAgent);

/** Not `[hidden]`, not `display:none` / `visibility:hidden`, and laid out. */
function isReachable(el: HTMLElement, host: HTMLElement): boolean {
  if (el.closest("[hidden]")) return false;
  for (let n: HTMLElement | null = el; n; n = n.parentElement) {
    const cs = getComputedStyle(n);
    if (cs.display === "none") return false;
    if (n === el && cs.visibility === "hidden") return false;
    if (n === host) break;
  }
  // jsdom has no layout: every element reports zero rects there.
  if (!isJsdom() && el.getClientRects().length === 0) return false;
  return true;
}

/** The overlay's focusable, reachable descendants in DOM order. */
export function overlayTabbables(host: HTMLElement): HTMLElement[] {
  return Array.from(host.querySelectorAll<HTMLElement>(OVERLAY_FOCUSABLE)).filter(
    (el) => isReachable(el, host),
  );
}

/** First reachable focusable inside the overlay, else the host itself. */
export function focusOverlay(host: HTMLElement) {
  (overlayTabbables(host)[0] ?? host).focus({ preventScroll: true });
}

/**
 * Keeps Tab / Shift+Tab inside the overlay. The rest of the editor is `inert`,
 * but a dialog's own focus scope ignores `inert` when it picks its first / last
 * candidate, so Tab from the overlay's last control would otherwise stick (or
 * leave the page) instead of wrapping.
 */
export function wrapTabWithinOverlay(e: KeyboardEvent<HTMLElement>) {
  if (e.key !== "Tab" || e.defaultPrevented) return;
  const host = e.currentTarget;
  const items = overlayTabbables(host);
  const active = document.activeElement;
  if (items.length === 0) {
    e.preventDefault();
    host.focus({ preventScroll: true });
    return;
  }
  const first = items[0]!;
  const last = items[items.length - 1]!;
  if (e.shiftKey && (active === first || active === host)) {
    e.preventDefault();
    last.focus({ preventScroll: true });
  } else if (!e.shiftKey && active === last) {
    e.preventDefault();
    first.focus({ preventScroll: true });
  }
}

import type Konva from "konva";

/** Name given to the base image node in `EditorCanvas`, so placement can find it. */
export const BASE_IMAGE_NODE_NAME = "media-editor-base-image";

export interface PlacementPoint {
  x: number;
  y: number;
}

interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

/**
 * Centre of the part of the image the user can currently see, in stage
 * coordinates (the space overlay `x` / `y` live in). The visible part is the
 * image rect intersected with the viewport after pan / zoom. With no image
 * yet, or the image panned fully out of view, it is the viewport centre.
 * `null` when the stage has not mounted.
 */
export function visibleImageCenter(stage: Konva.Stage | null): PlacementPoint | null {
  if (!stage) return null;
  const scale = stage.scaleX() || 1;
  const viewport: Rect = {
    x: -stage.x() / scale,
    y: -stage.y() / scale,
    width: stage.width() / scale,
    height: stage.height() / scale,
  };
  const node = stage.findOne(`.${BASE_IMAGE_NODE_NAME}`);
  const image: Rect | null = node
    ? { x: node.x(), y: node.y(), width: node.width(), height: node.height() }
    : null;
  const visible = image ? intersect(image, viewport) : null;
  const area = visible ?? viewport;
  return { x: area.x + area.width / 2, y: area.y + area.height / 2 };
}

function intersect(a: Rect, b: Rect): Rect | null {
  const x = Math.max(a.x, b.x);
  const y = Math.max(a.y, b.y);
  const right = Math.min(a.x + a.width, b.x + b.width);
  const bottom = Math.min(a.y + a.height, b.y + b.height);
  if (right <= x || bottom <= y) return null;
  return { x, y, width: right - x, height: bottom - y };
}

const isJsdom = () =>
  typeof navigator !== "undefined" && /jsdom/i.test(navigator.userAgent);

let measureContext: CanvasRenderingContext2D | null | undefined;

/** Quote family names that contain spaces, the way Konva builds its font string. */
function cssFontFamily(family: string): string {
  return family
    .split(",")
    .map((f) => {
      const name = f.trim();
      return /\s/.test(name) && !/^["']/.test(name) ? `"${name}"` : name;
    })
    .join(", ");
}

/**
 * Size of a Konva text node with default padding / line height (1), measured
 * the way Konva measures it (canvas `measureText`). Without a 2D context
 * (jsdom, SSR) it falls back to an estimate of 0.6em per character.
 */
export function measureTextBox(
  text: string,
  fontFamily: string,
  fontSize: number,
): { width: number; height: number } {
  const lines = text.split("\n");
  if (measureContext === undefined) {
    measureContext =
      typeof document === "undefined" || isJsdom()
        ? null
        : document.createElement("canvas").getContext("2d");
  }
  let width: number;
  if (measureContext) {
    measureContext.font = `${fontSize}px ${cssFontFamily(fontFamily)}`;
    width = Math.max(...lines.map((l) => measureContext!.measureText(l).width));
  } else {
    width = Math.max(...lines.map((l) => l.length)) * fontSize * 0.6;
  }
  return { width, height: lines.length * fontSize };
}

/** Used only if an overlay is added before the stage has mounted. */
export const FALLBACK_PLACEMENT: PlacementPoint = { x: 100, y: 200 };
